import './App.css';
import { useState } from "react";

function App() {
  const [rate, changeRate] = useState(0.0);
  const descriptionMessage = <p>Add descriptions</p>
  const resultsDividerLine = <hr />
  const [mortgageType, setMortgageType] = useState("Fixed Rate");
  const [resultValues, setResultValues] = useState ({
    totalLoanAmount: 0,
    monthlyMortgageRepayment: 0,
    totalRepaymentAmount: 0, 
    totalInterestPaid: 0, 
    ltvRatio: 0
  })

  const resultsCalculations = () => {
    const mortgageDuration = parseFloat(document.getElementById("mortgageDuration").value);
    const interestRate = parseFloat(rate);
    const propertyValue = parseFloat(document.getElementById("propertyValue").value);
    const depositAmount = parseFloat(document.getElementById("depositAmount").value);

    const totalLoanAmount =  propertyValue - depositAmount
    const monthlyRateValue = interestRate/100/12
    const totalMortgageMonths = mortgageDuration * 12

    let monthlyMortgageRepayment = 0;
    let totalRepaymentAmount = 0;
    let totalInterestPaid = 0;

    let numerator = (monthlyRateValue * Math.pow(1+monthlyRateValue, totalMortgageMonths))
    let denominator = (Math.pow(1+monthlyRateValue, totalMortgageMonths) - 1)
    let mortgagePaymentFormula = numerator/denominator

    if (mortgageType === "Fixed Rate" || mortgageType === "Adjustable Rate") {
      monthlyMortgageRepayment = totalLoanAmount * mortgagePaymentFormula;
      totalRepaymentAmount = monthlyMortgageRepayment * totalMortgageMonths;
      totalInterestPaid = totalRepaymentAmount - totalLoanAmount;
    }


    if (mortgageType === "Interest Only") {
      const interestOnlyPeriodValue = parseFloat(document.getElementById("interestOnlyPeriod").value);
      const interestOnlymonthsValue = interestOnlyPeriodValue * 12 
      const interestOnlyPaymentValue = totalLoanAmount * monthlyRateValue;
      const monthsRemaining = totalMortgageMonths - interestOnlymonthsValue;
      let interestOnlyFormula = (monthlyRateValue * Math.pow(1+monthlyRateValue, monthsRemaining))/
      (Math.pow(1+monthlyRateValue, monthsRemaining) - 1)
      const payment = totalLoanAmount * interestOnlyFormula;
      monthlyMortgageRepayment = interestOnlyPaymentValue;

      totalRepaymentAmount = (interestOnlyPaymentValue * interestOnlymonthsValue) + 
      (payment * monthsRemaining);

      totalInterestPaid = totalRepaymentAmount - totalLoanAmount;
    }
    const ltvRatio = (totalLoanAmount/propertyValue) * 100;
    setResultValues({totalLoanAmount, monthlyMortgageRepayment, totalRepaymentAmount, totalInterestPaid, 
        ltvRatio});
  }

  return (
    <>
    <div className = " header"></div>
    <h1>MORTGAGE CALCULATOR</h1>
    <h2 className = "appExplanation">Add application description</h2>

    <div className = "allContent">
      <div className = "inputsArea">
        <h3>Mortgage Details</h3> 
        <div className = "inputs">
          <label htmlFor="mortgageType">Mortgage Type</label>
          <select
          id = "mortgageType"
          value={mortgageType}
          onChange={(e) => setMortgageType(e.target.value)}
          >
            <option>Fixed Rate</option>
            <option>Interest Only</option>
          </select>
          {descriptionMessage}
        </div>

        <div className = "inputs">
          <label htmlFor="mortgageDuration">Mortgage Duration (years)</label>
          <input type="number" id="mortgageDuration" placeholder="e.g. 10" min="1"/>
          {descriptionMessage}
        </div>

        <div className = "inputs">
          <div className = "InterestRateSlider">
            <h4>Interest Rate in %</h4>
            <input 
            type="range" 
            min="1" 
            max="20" 
            step="0.01"
            value={rate}
            className = "slider"
            onChange={(e) => changeRate(parseFloat(e.target.value))}
            />

            <input 
            type = "number"
            min="1" 
            max="20"
            step="0.01"
            value={rate}
            onChange={(e) => changeRate(parseFloat(e.target.value))}
            />

          </div>
          {descriptionMessage}
        </div>

        {mortgageType === "Interest Only" && (
          <div className = "inputs">
            <label htmlFor="interestOnlyPeriod">Interest-Only Period in years</label>
            <input type="number" id="interestOnlyPeriod" placeholder="e.g. 3" min="1"/>
            {descriptionMessage}
          </div>
        )}

          <h3>Property details</h3>

          <div className = "inputs">
            <label htmlFor="propertyValue">Property Value</label>
            <input type="number" id="propertyValue" placeholder="e.g. 123,456" min="1"/>
            {descriptionMessage}
          </div>

          <div className = "inputs">
            <label htmlFor="depositAmount">Deposit Amount</label>
            <input type="number" id="depositAmount" placeholder="e.g. 50,000" min="1"/>
            {descriptionMessage}
          </div>

        <div className = "decisionButtons">
          <button onClick={resultsCalculations}className = "calculateButton">Calculate</button>
        </div>

      </div>

      <div className = "resultsArea">

        <div className = "resultValues">
          <h2>Results</h2>
          <div className="result">
            <h3>Loan amount</h3>
            <h3>{resultValues.totalLoanAmount}</h3>

          </div>
          {resultsDividerLine}

          <div className="result">
            <h3>Monthly mortgage payment</h3>
            <h3>{resultValues.monthlyMortgageRepayment}</h3>
          </div>
          {resultsDividerLine}

          <div className="result">
            <h3>Total repayment</h3>
            <h3>{resultValues.totalRepaymentAmount}</h3>
          </div>
          {resultsDividerLine}

          <div className="result">
            <h3>Total interest paid</h3>
            <h3>{resultValues.totalInterestPaid}</h3>
          </div>
          {resultsDividerLine}

          <div className="result">
            <h3>Loan to value (LTV) ratio</h3>
            <h3>{resultValues.ltvRatio}</h3>
          </div>

        </div>

        <div className = "graph"></div>

      </div>

    </div>

    </>
  );
}

export default App;
